using WPFUI.Models;

namespace WPFUI.Actions;
public class AttackWithWeapon
{
    private readonly GameItem _weapon;
    private readonly int _minmumDamage;
    private readonly int _maximumDamage;

    public event EventHandler<string> OnActionPerformed;

    public AttackWithWeapon(GameItem weapon, int minimumDamage, int maximumDamage)
    {
        if(weapon.Category != GameItem.ItemCategory.Weapon)
        {
            throw new ArgumentException($"{weapon.Name} is not a Weapon");
        }
        if(_minmumDamage < 0)
        {
            throw new ArgumentException($"minimum Damage must be larger than 0");
        }
        if(_maximumDamage < _minmumDamage)
        {
            throw new ArgumentException("maximum Damage must be >= than minimum Damage");
        }
        _weapon = weapon;
        _minmumDamage = minimumDamage;
        _maximumDamage = maximumDamage;
    }

    public void Execute(LivingEntity actor, LivingEntity target)
    {
        int damage = RandomNumberGenerator.NumberBetween(_minmumDamage, _maximumDamage);
        if(damage == 0)
        {
            ReportResult($"You missed the {target.Name.ToLower()}.");
        }
        else
        {
            ReportResult($"You hit the {target.Name.ToLower()} for {damage} points.");
        }
    }

    private void ReportResult(string result)
    {
        OnActionPerformed?.Invoke(this, result);
    }
}

