namespace WPFUI.ViewModels;
using System.ComponentModel;
using WPFUI.Models;
using WPFUI.Factories;
using System.Linq;
using WPFUI.EventArgs;
using System.Dynamic;

public class GameSession : BaseNotificationClass
{   
    public event EventHandler<GameMessageEventArgs> OnMessageRaised;
    private Location? _currentLocation;
    private Monster _currentMonster;
    private Player _currentPlayer;
    private Trader _currentTrader;
    public World CurrentWorld { get; }
    public Player CurrentPlayer { 
        get{return _currentPlayer;}
        set{
            if(_currentPlayer != null)
            {   
                _currentPlayer.OnLeveledUp -= OnCurrentPlayerLeveledUp;
                _currentPlayer.OnKilled -= OnCurrentPlayerKilled;
            }
            _currentPlayer = value;
            if(_currentPlayer != null)
            {   
                _currentPlayer.OnLeveledUp += OnCurrentPlayerLeveledUp;
                _currentPlayer.OnKilled += OnCurrentPlayerKilled;
            }
        }
    }
    public Location CurrentLocation { 
    get{return _currentLocation;}
    set{
        _currentLocation = value;
        OnPropertyChanged();
        OnPropertyChanged(nameof(HasLocationToNorth));
        OnPropertyChanged(nameof(HasLocationToWest));
        OnPropertyChanged(nameof(HasLocationToEast));
        OnPropertyChanged(nameof(HasLocationToSouth));

        CompleteQuestsAtLocation();
        GivePlayerQuestsAtLocation();
        GetMonsterAtLocation();

        CurrentTrader = CurrentLocation.TraderHere;
        }
    }

    public Monster CurrentMonster
    {
        get{return _currentMonster;}
        set{
            if(_currentMonster != null)
            {
                _currentMonster.OnKilled -= OnCurrentMonsterKilled;
            }
            _currentMonster = value;

            if(CurrentMonster != null)
            {   
                _currentMonster.OnKilled += OnCurrentMonsterKilled;
                RaiseMessage($"");
                RaiseMessage($"You see a {CurrentMonster.Name} here!");
            }
            OnPropertyChanged();
            OnPropertyChanged(nameof(HasMonster));
        }
    }
    public GameItem CurrentWeapon {get; set;}

    public Trader CurrentTrader
    {
        get{return _currentTrader;}
        set
        {
            _currentTrader = value;
            OnPropertyChanged();
            OnPropertyChanged(nameof(HasTrader));
        }
    }
    public bool HasLocationToNorth => CurrentWorld.LocationAt(CurrentLocation.XCoordinate, CurrentLocation.YCoordinate + 1) != null;
    public bool HasLocationToWest => CurrentWorld.LocationAt(CurrentLocation.XCoordinate - 1, CurrentLocation.YCoordinate) != null;

    public bool HasLocationToEast => CurrentWorld.LocationAt(CurrentLocation.XCoordinate + 1, CurrentLocation.YCoordinate) != null;


    public bool HasLocationToSouth =>  CurrentWorld.LocationAt(CurrentLocation.XCoordinate, CurrentLocation.YCoordinate - 1) != null;

    public bool HasMonster => CurrentMonster != null;
    public bool HasTrader => CurrentTrader != null;

    public GameSession(Player player)
    {
        CurrentPlayer = player;

        if (!CurrentPlayer.Weapons.Any())
        {
            CurrentPlayer.AddItemToInventory(ItemFactory.CreateGameItem(1001));
        }

        CurrentWorld = WorldFactory.CreateWorld();

        CurrentLocation = CurrentWorld.LocationAt(0, -1);
    }

    public void MoveNorth()
    {   
        if (HasLocationToNorth){
            CurrentLocation = CurrentWorld.LocationAt(CurrentLocation.XCoordinate, CurrentLocation.YCoordinate + 1);
        }
    }

    public void MoveWest()
    {
        if (HasLocationToWest){
            CurrentLocation = CurrentWorld.LocationAt(CurrentLocation.XCoordinate - 1, CurrentLocation.YCoordinate);
        }
    }


    public void MoveEast()
    {
        if (HasLocationToEast){
            CurrentLocation = CurrentWorld.LocationAt(CurrentLocation.XCoordinate + 1, CurrentLocation.YCoordinate);
        }
    }

    public void MoveSouth()
    {
        if (HasLocationToSouth){
            CurrentLocation = CurrentWorld.LocationAt(CurrentLocation.XCoordinate, CurrentLocation.YCoordinate - 1);
        }
    }

    private void GivePlayerQuestsAtLocation()
    {
        foreach (Quest quest in CurrentLocation.QuestsAvailableHere)
        {
            if (!CurrentPlayer.Quests.Any(q => q.Quest.Id == quest.Id))
            {
                CurrentPlayer.Quests.Add(new QuestStatus(quest));
                RaiseMessage("");
                RaiseMessage($"You received the {quest.Name} quest");
                RaiseMessage(quest.Description);
                RaiseMessage("return with:");
                foreach(ItemQuantity item in quest.CompleteItems)
                {
                    RaiseMessage($"   {item.Quantity} {ItemFactory.CreateGameItem(item.ItemID).Name}");
                }
                RaiseMessage("And you will receive");
                RaiseMessage($"   {quest.RewardExperiencePoints} experience points");
                RaiseMessage($"   {quest.RewardGold} gold");
                foreach(ItemQuantity itemQuantity in quest.RewardItems)
                {
                    RaiseMessage($"   {itemQuantity.Quantity} {ItemFactory.CreateGameItem(itemQuantity.ItemID).Name}");
                }
            }
        }
    }

    private void CompleteQuestsAtLocation()
    {
        foreach(Quest quest in CurrentLocation.QuestsAvailableHere)
        {
            QuestStatus? questToComplete =
                CurrentPlayer.Quests.FirstOrDefault(q => q.Quest.Id == quest.Id &&
                                                            !q.IsCompleted);

            if(questToComplete != null)
            {
                if(CurrentPlayer.HasAllItems(quest.CompleteItems))
                {
                    // Remove the quest completion items from the player's inventory
                    foreach (ItemQuantity itemQuantity in quest.CompleteItems)
                    {
                        for(int i = 0; i < itemQuantity.Quantity; i++)
                        {
                            CurrentPlayer.RemoveItemFromInventory(CurrentPlayer.Inventory.First(item => item.ItemTypeId == itemQuantity.ItemID));
                        }
                    }

                    RaiseMessage("");
                    RaiseMessage($"You completed the '{quest.Name}' quest");

                    // Give the player the quest rewards
                    RaiseMessage($"You receive {quest.RewardExperiencePoints} experience points");
                    CurrentPlayer.AddExperience(quest.RewardExperiencePoints);

                    RaiseMessage($"You receive {quest.RewardGold} gold");        
                    CurrentPlayer.ReceiveGold(quest.RewardGold);


                    foreach(ItemQuantity itemQuantity in quest.RewardItems)
                    {
                        GameItem rewardItem = ItemFactory.CreateGameItem(itemQuantity.ItemID);

                        RaiseMessage($"You receive a {rewardItem.Name}");
                        CurrentPlayer.AddItemToInventory(rewardItem);
                    }

                    // Mark the Quest as completed
                    questToComplete.IsCompleted = true;
                }
            }
        }
    }
    private void GetMonsterAtLocation()
    {
        CurrentMonster = CurrentLocation.GetMonster();
    }

    private void RaiseMessage(string message)
    {
        OnMessageRaised?.Invoke(this, new GameMessageEventArgs(message));
    }

    public void AttackCurrentMonster()
    {
        if (CurrentWeapon == null)
        {
            RaiseMessage("You must select a Weapon");
            return;
        }
        CurrentPlayer.UseCurrentWeaponOn(CurrentMonster);
        if(CurrentMonster.isDead)
        {
            GetMonsterAtLocation();
        }
        else
        {
            int damageToPlayer = RandomNumberGenerator.NumberBetween(CurrentMonster.MinDamage, CurrentMonster.MaxDamage);
            if(damageToPlayer == 0)
            {
                RaiseMessage("The monster attack missed you");
            }
            else
            {
                RaiseMessage($"You received {damageToPlayer} damage from the {CurrentMonster.Name}");
                CurrentPlayer.TakeDamage(damageToPlayer);
            }

        }
    }
    private void OnCurrentPlayerPerformedAction(object sender, string result)
    {
        RaiseMessage(result);
    }
    private void OnCurrentPlayerKilled(object sender, System.EventArgs eventArgs)
    {
        RaiseMessage("");
        RaiseMessage($"You have been killed");

        CurrentLocation = CurrentWorld.LocationAt(0, -1);
        CurrentPlayer.CompleteHeal();
    }

    private void OnCurrentMonsterKilled(object sender, System.EventArgs eventArgs)
    {
        RaiseMessage("");
        RaiseMessage($"You defeated the {CurrentMonster. Name}");

        RaiseMessage($"You receive {CurrentMonster.RewardedExperiencePoints} experience points");
        CurrentPlayer.AddExperience(CurrentMonster.RewardedExperiencePoints);

        RaiseMessage($"You receive {CurrentMonster.Gold} gold");
        CurrentPlayer.ReceiveGold(CurrentMonster.Gold);

        foreach(GameItem gameItem in CurrentMonster.Inventory)
        {
            RaiseMessage($"You receive {gameItem.Name}");
            CurrentPlayer.AddItemToInventory(gameItem);
        }

    }

    private void OnCurrentPlayerLeveledUp(object sender, System.EventArgs eventArgs)
    {
        RaiseMessage($"You are now Level {CurrentPlayer.Level}");
    }

}

